import{_ as r,C as n,o as t,c as s,a5 as a,b as c,w as i,a as d,E as l,a7 as h}from"./chunks/framework.QWVCgkrI.js";const B=JSON.parse('{"title":"Gitのリモート追跡ブランチ — origin/mainはサーバーそのものではない","description":"","frontmatter":{"title":"Gitのリモート追跡ブランチ — origin/mainはサーバーそのものではない","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"手元のmain・origin/main・共有先のmainを区別し、fetchで追跡参照が動くとahead/behindの数字がどう変わるかを読む。","aliases":["Git remote-tracking branch","remote-tracking ref","origin/main","upstream","リモート追跡参照","Git fetch","ahead/behind"],"verification":"Git公式資料に照合し、Windows上の独立した共有先と2つの作業用リポジトリでfetch前後の状態を確認（2026-11-17）"}},"headers":[],"relativePath":"tools/git-remote-tracking.md","filePath":"tools/git-remote-tracking.md"}'),m={name:"tools/git-remote-tracking.md"};function g(p,e,f,E,b,u){const o=n("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="gitのリモート追跡ブランチ-—-origin-mainはサーバーそのものではない" tabindex="-1">Gitのリモート追跡ブランチ — origin/mainはサーバーそのものではない <a class="header-anchor" href="#gitのリモート追跡ブランチ-—-origin-mainはサーバーそのものではない" aria-label="Permalink to &quot;Gitのリモート追跡ブランチ — origin/mainはサーバーそのものではない&quot;">​</a></h1><p>同僚が共有先にステージの変更をpushしたとします。手元で <code>git status</code> を見ると、ステージの変更をまだ取り込んでいないのに、<code>behind</code> は表示されません。この例で <code>git status</code> が比較するのは、手元の <code>main</code> と、共有先の先端を最後に記録した手元の <code>origin/main</code> です。その記録が更新されると、作業ファイルの内容が同じでも進み・遅れの表示が変わります。<a href="https://git-scm.com/book/en/v2/Git-Branching-Remote-Branches" target="_blank" rel="noreferrer">Pro GitのRemote Branches</a></p><h2 id="二つのリポジトリに三つの参照がある" tabindex="-1">二つのリポジトリに三つの参照がある <a class="header-anchor" href="#二つのリポジトリに三つの参照がある" aria-label="Permalink to &quot;二つのリポジトリに三つの参照がある&quot;">​</a></h2><p><code>origin</code> は手元のGitに登録した接続先の名前です。通常のcloneが付ける名前で、別の名前にもできます。次の三つの参照は別々の操作で更新されます。<a href="/study/tools/git-objects.html">Gitの保存モデル</a> · <a href="https://git-scm.com/docs/gitglossary#def_remote_tracking_branch" target="_blank" rel="noreferrer">Git公式の用語集</a></p><ul><li><strong>手元の <code>main</code></strong> (<code>refs/heads/main</code>) は、自分の作業ブランチの先端です。<code>main</code> 上でコミットすると、この参照が進みます。</li><li><strong>手元の <code>origin/main</code></strong> (<code>refs/remotes/origin/main</code>) は、接続先 <code>origin</code> の <code>main</code> がどこを指していたかを手元に記録するリモート追跡ブランチです。</li><li><strong>共有先の <code>main</code></strong> (<code>refs/heads/main</code>) は、共有先リポジトリにあるブランチの先端です。共有先が受け付けたpushなどで更新されます。</li></ul><h2 id="fetchで-origin-main-が更新される" tabindex="-1">fetchで <code>origin/main</code> が更新される <a class="header-anchor" href="#fetchで-origin-main-が更新される" aria-label="Permalink to &quot;fetchで `origin/main` が更新される&quot;">​</a></h2><p>Aの時点では、三つの参照が同じコミットを指していました。そこから同僚がゲーム内のステージ番号を <code>stage=2</code> にするコミットBを共有先にpushし、自分はAから敵のHPを <code>hp=2</code> にするコミットCを手元で作りました。fetch前の <code>origin/main</code> は、まだAを指しています。図の参照から出る矢印は、その名前が指すコミットを示します。コミットから出る「親」の矢印は別の関係です。</p>',7)),(t(),c(h,null,{default:i(()=>[l(o,{id:"mermaid-35",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20flowchart%3A%0A%20%20%20%20nodeSpacing%3A%2018%0A%20%20%20%20rankSpacing%3A%2038%0A%20%20%20%20padding%3A%208%0A---%0Aflowchart%20TD%0A%20%20%20%20accTitle%3A%20fetch%E5%89%8D%E5%BE%8C%E3%81%AEmain%E3%81%A8origin%2Fmain%0A%20%20%20%20accDescr%3A%20%E6%89%8B%E5%85%83%E3%81%AEmain%E3%81%AFC%E3%80%81%E5%85%B1%E6%9C%89%E5%85%88%E3%81%AEmain%E3%81%AFB%E3%82%92%E6%8C%87%E3%81%97%E7%B6%9A%E3%81%91%E3%82%8B%E3%80%82%E6%89%8B%E5%85%83%E3%81%AEorigin%2Fmain%E3%81%A0%E3%81%91%E3%81%8Cfetch%E5%89%8D%E3%81%AEA%E3%81%8B%E3%82%89fetch%E5%BE%8C%E3%81%AEB%E3%81%B8%E7%A7%BB%E3%82%8B%E3%80%82B%E3%81%A8C%E3%81%AE%E8%A6%AA%E3%81%AFA%E3%80%82%0A%20%20%20%20work%5B%22%E6%89%8B%E5%85%83%20main%22%5D%20--%3E%20c%5B%22C%20HP%E3%82%92%E5%A4%89%E6%9B%B4%22%5D%0A%20%20%20%20tracking%5B%22%E6%89%8B%E5%85%83%20origin%2Fmain%22%5D%20-.%20fetch%E5%89%8D%20.-%3E%20a%5B%22A%20%E5%85%B1%E9%80%9A%E3%81%AE%E8%B5%B7%E7%82%B9%22%5D%0A%20%20%20%20tracking%20--%3E%7Cfetch%E5%BE%8C%7C%20b%5B%22B%20%E3%82%B9%E3%83%86%E3%83%BC%E3%82%B8%E3%82%92%E5%A4%89%E6%9B%B4%22%5D%0A%20%20%20%20shared%5B%22%E5%85%B1%E6%9C%89%E5%85%88%20main%22%5D%20--%3E%20b%0A%20%20%20%20c%20--%3E%7C%E8%A6%AA%7C%20a%0A%20%20%20%20b%20--%3E%7C%E8%A6%AA%7C%20a%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>この例の <code>git fetch origin</code> は、共有先のBを読むために必要なオブジェクトを取得し、手元の <code>origin/main</code> をBへ更新します。手元の <code>main</code> はCのままです。GitはBの設定を <code>origin/main:stage.txt</code> として読めますが、作業ツリーの <code>stage.txt</code> は <code>stage=1</code> のままです。indexにもBの変更は入りません。<a href="https://git-scm.com/docs/git-fetch#_description" target="_blank" rel="noreferrer">Git公式のfetchマニュアル</a> · <a href="/study/tools/git-staging-index.html">Gitのステージング</a></p><p>全ブランチを対象とする通常のcloneでは <code>remote.origin.fetch</code> に <code>+refs/heads/*:refs/remotes/origin/*</code> が設定されます。コロンの左が共有先から取得する参照の範囲で、右が手元で更新する参照の場所です。この対応なら共有先の <code>refs/heads/main</code> の値が、手元の <code>refs/remotes/origin/main</code> に記録されます。実際に取得・更新される参照は設定やfetchの引数で変わります。<a href="https://git-scm.com/docs/git-fetch#CRTB" target="_blank" rel="noreferrer">Git公式のfetchの参照対応</a></p><h2 id="ahead-behindは二つの手元の履歴を数える" tabindex="-1">ahead/behindは二つの手元の履歴を数える <a class="header-anchor" href="#ahead-behindは二つの手元の履歴を数える" aria-label="Permalink to &quot;ahead/behindは二つの手元の履歴を数える&quot;">​</a></h2><p><code>git status</code> は、現在の作業ブランチと、設定された上流ブランチ（upstream）を比較します。この例で <code>main</code> のupstreamは <code>origin/main</code> です。aheadは <code>main</code> だけからたどれるコミット数、behindは <code>origin/main</code> だけからたどれるコミット数です。Aのように両方からたどれるコミットや、コミットしていない編集は数に入りません。<a href="https://git-scm.com/docs/git-status#_options" target="_blank" rel="noreferrer">Git公式のstatusマニュアル</a> · <a href="https://git-scm.com/docs/git-rev-list" target="_blank" rel="noreferrer">Git公式のrev-listマニュアル</a></p><table tabindex="0"><thead><tr><th>参照と比較結果</th><th>fetch前</th><th>fetch後</th></tr></thead><tbody><tr><td>手元の <code>main</code></td><td>C</td><td>C</td></tr><tr><td>手元の <code>origin/main</code></td><td>A</td><td>B</td></tr><tr><td>共有先の <code>main</code></td><td>B</td><td>B</td></tr><tr><td>ahead / behind</td><td>1 / 0</td><td>1 / 1</td></tr></tbody></table><p>fetch前はCとAを比較するので ahead 1 / behind 0 です。fetchすると比較相手がBに変わり、CとBがそれぞれ片側だけにあるため ahead 1 / behind 1 になります。<code>git status</code> 自体は共有先に問い合わせません。新しいfetchで基準を更新した直後でも、共有先に次のpushが届けば差が生まれます。また、手元でコミットすれば、共有先が進まなくても数は変わります。<a href="https://git-scm.com/book/en/v2/Git-Branching-Remote-Branches" target="_blank" rel="noreferrer">Pro Gitの追跡ブランチ</a></p><p>次は手元の作業用リポジトリでの実測です。<code>git ls-remote</code> で共有先へ問い合わせると、BのIDは <code>54d6232</code> から始まります。その問い合わせだけでは手元の <code>origin/main</code> はAのままです。<code>rev-list</code> は <code>main</code> 側、<code>origin/main</code> 側の順で、片側だけからたどれるコミットを数えます。fetchの出力は更新を示す行だけを載せています。<a href="https://git-scm.com/docs/git-ls-remote" target="_blank" rel="noreferrer">Git公式のls-remoteマニュアル</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git ls-remote --refs origin refs/heads/main</span></span>
<span class="line"><span>54d623297de0346e7577bf338ae92d7efc6068bb	refs/heads/main</span></span>
<span class="line"><span>$ git rev-parse --short origin/main</span></span>
<span class="line"><span>4a7d0c7</span></span>
<span class="line"><span>$ git rev-list --left-right --count main...origin/main</span></span>
<span class="line"><span>1	0</span></span>
<span class="line"><span>$ git fetch origin</span></span>
<span class="line"><span>   4a7d0c7..54d6232  main       -&gt; origin/main</span></span>
<span class="line"><span>$ git rev-list --left-right --count main...origin/main</span></span>
<span class="line"><span>1	1</span></span>
<span class="line"><span>$ git status --short --branch</span></span>
<span class="line"><span>## main...origin/main [ahead 1, behind 1]</span></span>
<span class="line"><span>$ git show origin/main:stage.txt</span></span>
<span class="line"><span>stage=2</span></span></code></pre></div><h2 id="取得と統合は別の操作" tabindex="-1">取得と統合は別の操作 <a class="header-anchor" href="#取得と統合は別の操作" aria-label="Permalink to &quot;取得と統合は別の操作&quot;">​</a></h2><p>Bを作業ブランチに取り込むには、取得したコミットを統合する操作が続きます。fast-forwardで先端をCからBへ移すには、BがCの子孫であることが条件です。この例のBとCはAから分岐しています。mergeなら二つの先端を親とする結果を作る方法があり、rebaseならCの変更をBの上に再適用する方法があります。<code>git pull</code> はfetchの後に統合を試みます。統合方法や、分岐したときに停止するかは設定やオプションで決まります。<a href="https://git-scm.com/docs/git-pull#_description" target="_blank" rel="noreferrer">Git公式のpullマニュアル</a> · <a href="/study/tools/git-three-way-merge.html">Gitのマージ</a> · <a href="/study/tools/git-rebase.html">Gitのrebase</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>共有先の <code>main</code> が進んでも、手元では遅れ0件になることはある？</summary><p>あります。この例のfetch前は、追跡参照がAを指しています。共有先はBまで進んでいますが、手元の比較にはまだBが含まれません。</p></details><details class="details custom-block"><summary>fetch後、<code>origin/main:stage.txt</code> に <code>stage=2</code> があると、作業ツリーもその内容になる？</summary><p>この例の作業ツリーは <code>stage=1</code> のままです。<code>origin/main:stage.txt</code> はBのスナップショットを読み、作業ツリーは手元の <code>main</code> 上で編集しているファイルです。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月17日に、WindowsのGit 2.39.2.windows.1を使い、SHA-1のbareリポジトリをローカルの共有先にして二つの作業用リポジトリで確認しました。通常のfetchの参照対応と <code>main</code> のupstreamを使い、共有先への通常のpush後と、もう一方のリポジトリでfetchした後の参照・コミット数・index・作業ファイルを比較しました。HTTPSやSSHの転送、浅いclone、独自の参照対応、共有先の履歴の書き換えは実測範囲外です。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-basics.html">Gitの基本</a> — 状態表示とコミットを確認する。</li><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> — 参照とコミットオブジェクトの関係を読む。</li><li><a href="/study/tools/git-three-way-merge.html">Gitのマージ</a> · <a href="/study/tools/git-rebase.html">Gitのrebase</a> — 取得したコミットを作業に統合する二つの考え方を比べる。</li><li><a href="/study/tools/git-reflog.html">Gitのreflog</a> — 手元で起きた参照の移動をたどる。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/gitglossary#def_remote_tracking_branch" target="_blank" rel="noreferrer">Git公式 — gitglossaryのremote-tracking branch</a></li><li><a href="https://git-scm.com/docs/git-fetch#CRTB" target="_blank" rel="noreferrer">Git公式 — git-fetch</a></li><li><a href="https://git-scm.com/docs/git-status#_options" target="_blank" rel="noreferrer">Git公式 — git-status</a></li><li><a href="https://git-scm.com/docs/git-rev-list" target="_blank" rel="noreferrer">Git公式 — git-rev-list</a></li><li><a href="https://git-scm.com/docs/git-ls-remote" target="_blank" rel="noreferrer">Git公式 — git-ls-remote</a></li><li><a href="https://git-scm.com/docs/git-pull#_description" target="_blank" rel="noreferrer">Git公式 — git-pull</a></li><li><a href="https://git-scm.com/book/en/v2/Git-Branching-Remote-Branches" target="_blank" rel="noreferrer">Pro Git — Remote Branches</a></li></ul>`,19))])}const _=r(m,[["render",g]]);export{B as __pageData,_ as default};
